"""Regression coverage for context-aware Maybe deciders."""

import pytest

import factory


@pytest.mark.parametrize('value', [0, 1])
@pytest.mark.parametrize('locale', [None, 'fr_FR'])
def test_faker_decider_defaults(value, locale):
    class ExampleFactory(factory.DictFactory):
        result = factory.Maybe(
            factory.Faker(
                'pyint', locale=locale,
                min_value=factory.LazyFunction(lambda: value),
                max_value=value,
            ),
            yes_declaration='yes',
            no_declaration='no',
        )

    assert ExampleFactory.create_batch(3) == [
        {'result': 'yes' if value else 'no'}
    ] * 3


@pytest.mark.parametrize('value', [False, True])
def test_nested_maybe_decider(value):
    class ExampleFactory(factory.DictFactory):
        result = factory.Maybe(
            factory.Maybe(
                factory.LazyFunction(lambda: value),
                yes_declaration=True,
                no_declaration=False,
            ),
            yes_declaration='yes',
            no_declaration='no',
        )

    assert ExampleFactory() == {'result': 'yes' if value else 'no'}
EOF
pytest --no-header -rA --tb=line --color=no -p no:cacheprovider -W ignore::DeprecationWarning tests/test_regression.py tests/test_maybe_decider_regression.py > "$TMPDIR/maybe-tests.log" 2>&1; result=$?; tail -n 35 "$TMPDIR/maybe-tests.log"; exit $result

